from pathlib import Path

path = Path("Display.h")
text = path.read_text(encoding="utf-8")
old = '    void ShowSchedule(\n        const Schedule &schedule,\n        const char *clockText,\n        const char *dateText,\n        int firstEntry,\n        int currentEntry,\n        int entriesForDate);\n'
new = '    void ShowSchedule(\n        const Schedule &schedule,\n        const char *clockText,\n        const char *dateText,\n        int pageStart,\n        int currentEntry,\n        bool hasPrevious,\n        bool hasNext);\n'
if old not in text:
    raise SystemExit("STOP: Display.h does not match the pushed multi-day baseline.")
path.write_text(text.replace(old, new, 1), encoding="utf-8")

path = Path("Display.cpp")
text = path.read_text(encoding="utf-8")
start = text.find("void Display::ShowSchedule(")
end = text.find("\nvoid Display::DrawBadge(", start)
if start < 0 or end < 0:
    raise SystemExit("STOP: Display.cpp ShowSchedule block was not found.")
new_show_schedule = 'void Display::ShowSchedule(\n    const Schedule &schedule,\n    const char *clockText,\n    const char *dateText,\n    int pageStart,\n    int currentEntry,\n    bool hasPrevious,\n    bool hasNext)\n{\n    ClearFrameBuffer();\n\n    DrawFittedText(\n        clockText,\n        20,\n        30,\n        DisplayLayout::Width - 40,\n        8,\n        true);\n\n    DrawFittedText(\n        dateText,\n        20,\n        110,\n        DisplayLayout::Width - 40,\n        3,\n        true);\n\n    if (pageStart >= 0 &&\n        pageStart < schedule.Count())\n    {\n        const ScheduleEntry &first =\n            schedule.Entry(pageStart);\n\n        if (first.Label[0] != \'\\0\')\n        {\n            DrawFittedText(\n                first.Label,\n                20,\n                155,\n                DisplayLayout::Width - 40,\n                4,\n                true);\n        }\n    }\n\n    DrawFittedText(\n        "SCHEDULE",\n        20,\n        205,\n        DisplayLayout::Width - 40,\n        4,\n        true);\n\n    if (pageStart < 0 ||\n        schedule.Count() == 0)\n    {\n        DrawFittedText(\n            "NO EVENTS",\n            20,\n            340,\n            DisplayLayout::Width - 40,\n            5,\n            true);\n    }\n    else\n    {\n        const ScheduleEntry &pageDate =\n            schedule.Entry(pageStart);\n\n        int y = 285;\n        int displayed = 0;\n\n        for (int i = pageStart;\n             i < schedule.Count() &&\n             displayed < 4;\n             i++)\n        {\n            const ScheduleEntry &entry =\n                schedule.Entry(i);\n\n            if (entry.Year != pageDate.Year ||\n                entry.Month != pageDate.Month ||\n                entry.Day != pageDate.Day)\n            {\n                break;\n            }\n\n            uint8_t textColor =\n                i == currentEntry\n                ? 0x88\n                : 0x00;\n\n            DrawText(\n                entry.Time,\n                30,\n                y,\n                4,\n                textColor);\n\n            DrawFittedText(\n                entry.Title,\n                170,\n                y,\n                DisplayLayout::Width - 190,\n                4,\n                false,\n                textColor);\n\n            if (entry.Location[0] != \'\\0\')\n            {\n                DrawFittedText(\n                    entry.Location,\n                    170,\n                    y + 45,\n                    DisplayLayout::Width - 190,\n                    3,\n                    false,\n                    textColor);\n            }\n\n            y += 125;\n            displayed++;\n        }\n    }\n\n    FillRectangle(\n        20,\n        835,\n        DisplayLayout::Width - 40,\n        2,\n        0x00);\n\n    if (hasPrevious)\n    {\n        DrawFittedText(\n            "< PREV",\n            10,\n            875,\n            165,\n            3,\n            true);\n    }\n\n    DrawFittedText(\n        "MENU",\n        185,\n        875,\n        170,\n        3,\n        true);\n\n    if (hasNext)\n    {\n        DrawFittedText(\n            "NEXT >",\n            365,\n            875,\n            165,\n            3,\n            true);\n    }\n\n    RefreshFull();\n}\n'
text = text[:start] + new_show_schedule + text[end:]
path.write_text(text, encoding="utf-8")

path = Path("main.ino")
text = path.read_text(encoding="utf-8")

marker = 'namespace MenuLayout\n{\n    constexpr int Left = 40;\n    constexpr int Width = 460;\n\n    constexpr int BadgeTop = 240;\n    constexpr int BadgeBottom = 390;\n\n    constexpr int ScheduleTop = 410;\n    constexpr int ScheduleBottom = 560;\n\n    constexpr int PowerTop = 580;\n    constexpr int PowerBottom = 730;\n}\n'
replacement = 'namespace MenuLayout\n{\n    constexpr int Left = 40;\n    constexpr int Width = 460;\n\n    constexpr int BadgeTop = 240;\n    constexpr int BadgeBottom = 390;\n\n    constexpr int ScheduleTop = 410;\n    constexpr int ScheduleBottom = 560;\n\n    constexpr int PowerTop = 580;\n    constexpr int PowerBottom = 730;\n}\n\nnamespace ScheduleLayout\n{\n    constexpr int ButtonTop = 830;\n    constexpr int ButtonBottom = 960;\n\n    constexpr int PreviousLeft = 0;\n    constexpr int PreviousRight = 180;\n\n    constexpr int MenuLeft = 180;\n    constexpr int MenuRight = 360;\n\n    constexpr int NextLeft = 360;\n    constexpr int NextRight = 540;\n\n    constexpr int EntriesPerPage = 4;\n}\n'
if marker not in text:
    raise SystemExit("STOP: MenuLayout block does not match the pushed baseline.")
text = text.replace(marker, replacement, 1)

old = 'Screen currentScreen = Screen::Badge;\n\nvoid CheckTouch();\nvoid ShowMenu();\nvoid ShowBadge();\nvoid ShowSchedule();\n\nbool IsMenuSelection(\n    const TouchPoint &point,\n    int top,\n    int bottom);\n'
new = 'Screen currentScreen = Screen::Badge;\n\nint schedulePageStart = -1;\nint scheduleCurrentEntry = -1;\n\nvoid CheckTouch();\nvoid CheckScheduleTouch(const TouchPoint &point);\n\nvoid ShowMenu();\nvoid ShowBadge();\nvoid ShowSchedule();\nvoid DrawSchedulePage();\nvoid ShowNextSchedulePage();\nvoid ShowPreviousSchedulePage();\n\nint FindDateStart(int entryIndex);\nint FindDateEnd(int entryIndex);\nint FindPageStartForEntry(int entryIndex);\n\nbool HasNextSchedulePage();\nbool HasPreviousSchedulePage();\n\nbool IsMenuSelection(\n    const TouchPoint &point,\n    int top,\n    int bottom);\n\nbool IsTouchRegion(\n    const TouchPoint &point,\n    int left,\n    int right,\n    int top,\n    int bottom);\n'
if old not in text:
    raise SystemExit("STOP: main.ino declarations do not match the pushed baseline.")
text = text.replace(old, new, 1)

old = '    if (currentScreen == Screen::Badge ||\n        currentScreen == Screen::Schedule)\n    {\n        Serial.println("Opening menu.");\n        ShowMenu();\n        return;\n    }\n'
new = '    if (currentScreen == Screen::Badge)\n    {\n        Serial.println("Opening menu.");\n        ShowMenu();\n        return;\n    }\n\n    if (currentScreen == Screen::Schedule)\n    {\n        CheckScheduleTouch(point);\n        return;\n    }\n'
if old not in text:
    raise SystemExit("STOP: schedule touch dispatch does not match the pushed baseline.")
