start = text.find("void ShowSchedule()\n")
end = text.find("\nbool IsMenuSelection(", start)
if start < 0 or end < 0:
    raise SystemExit("STOP: main.ino ShowSchedule block was not found.")
new_schedule_code = 'void ShowSchedule()\n{\n    currentScreen = Screen::Schedule;\n\n    schedule.LoadFromSd();\n    rtcClock.Read();\n\n    schedulePageStart = -1;\n    scheduleCurrentEntry = -1;\n\n    if (schedule.Count() == 0)\n    {\n        DrawSchedulePage();\n        return;\n    }\n\n    int firstToday = -1;\n\n    if (rtcClock.IsValid())\n    {\n        firstToday =\n            schedule.FindFirstEntryForDate(\n                rtcClock.Year(),\n                rtcClock.Month(),\n                rtcClock.Day());\n\n        scheduleCurrentEntry =\n            schedule.FindCurrentEntry(\n                rtcClock.Year(),\n                rtcClock.Month(),\n                rtcClock.Day(),\n                rtcClock.Hour(),\n                rtcClock.Minute());\n    }\n\n    if (scheduleCurrentEntry >= 0)\n    {\n        schedulePageStart =\n            FindPageStartForEntry(\n                scheduleCurrentEntry);\n    }\n    else if (firstToday >= 0)\n    {\n        schedulePageStart =\n            firstToday;\n    }\n    else\n    {\n        schedulePageStart = 0;\n    }\n\n    DrawSchedulePage();\n}\n\nvoid DrawSchedulePage()\n{\n    char clockText[6];\n    char dateText[11];\n\n    rtcClock.FormatTime(\n        clockText,\n        sizeof(clockText));\n\n    if (schedulePageStart >= 0 &&\n        schedulePageStart < schedule.Count())\n    {\n        const ScheduleEntry &entry =\n            schedule.Entry(\n                schedulePageStart);\n\n        snprintf(\n            dateText,\n            sizeof(dateText),\n            "%04d-%02d-%02d",\n            entry.Year,\n            entry.Month,\n            entry.Day);\n    }\n    else\n    {\n        rtcClock.FormatDate(\n            dateText,\n            sizeof(dateText));\n    }\n\n    display.ShowSchedule(\n        schedule,\n        clockText,\n        dateText,\n        schedulePageStart,\n        scheduleCurrentEntry,\n        HasPreviousSchedulePage(),\n        HasNextSchedulePage());\n}\n\nvoid CheckScheduleTouch(\n    const TouchPoint &point)\n{\n    if (IsTouchRegion(\n            point,\n            ScheduleLayout::MenuLeft,\n            ScheduleLayout::MenuRight,\n            ScheduleLayout::ButtonTop,\n            ScheduleLayout::ButtonBottom))\n    {\n        Serial.println("Schedule MENU selected.");\n        ShowMenu();\n        return;\n    }\n\n    if (HasPreviousSchedulePage() &&\n        IsTouchRegion(\n            point,\n            ScheduleLayout::PreviousLeft,\n            ScheduleLayout::PreviousRight,\n            ScheduleLayout::ButtonTop,\n            ScheduleLayout::ButtonBottom))\n    {\n        Serial.println("Schedule PREV selected.");\n        ShowPreviousSchedulePage();\n        return;\n    }\n\n    if (HasNextSchedulePage() &&\n        IsTouchRegion(\n            point,\n            ScheduleLayout::NextLeft,\n            ScheduleLayout::NextRight,\n            ScheduleLayout::ButtonTop,\n            ScheduleLayout::ButtonBottom))\n    {\n        Serial.println("Schedule NEXT selected.");\n        ShowNextSchedulePage();\n        return;\n    }\n\n    Serial.println("Schedule touch was outside a navigation button.");\n}\n\nvoid ShowNextSchedulePage()\n{\n    if (!HasNextSchedulePage())\n    {\n        return;\n    }\n\n    int dateEnd =\n        FindDateEnd(\n            schedulePageStart);\n\n    int nextWithinDate =\n        schedulePageStart +\n        ScheduleLayout::EntriesPerPage;\n\n    if (nextWithinDate <= dateEnd)\n    {\n        schedulePageStart =\n            nextWithinDate;\n    }\n    else if (dateEnd + 1 < schedule.Count())\n    {\n        schedulePageStart =\n            dateEnd + 1;\n    }\n\n    DrawSchedulePage();\n}\n\nvoid ShowPreviousSchedulePage()\n{\n    if (!HasPreviousSchedulePage())\n    {\n        return;\n    }\n\n    int dateStart =\n        FindDateStart(\n            schedulePageStart);\n\n    if (schedulePageStart > dateStart)\n    {\n        schedulePageStart -=\n            ScheduleLayout::EntriesPerPage;\n\n        if (schedulePageStart < dateStart)\n        {\n            schedulePageStart =\n                dateStart;\n        }\n\n        DrawSchedulePage();\n        return;\n    }\n\n    int previousEntry =\n        dateStart - 1;\n\n    int previousDateStart =\n        FindDateStart(\n            previousEntry);\n\n    int previousDateEnd =\n        FindDateEnd(\n            previousEntry);\n\n    int count =\n        previousDateEnd -\n        previousDateStart +\n        1;\n\n    int lastPageOffset =\n        ((count - 1) /\n         ScheduleLayout::EntriesPerPage) *\n        ScheduleLayout::EntriesPerPage;\n\n    schedulePageStart =\n        previousDateStart +\n        lastPageOffset;\n\n    DrawSchedulePage();\n}\n\nint FindDateStart(\n    int entryIndex)\n{\n    if (entryIndex < 0 ||\n        entryIndex >= schedule.Count())\n    {\n        return -1;\n    }\n\n    const ScheduleEntry &target =\n        schedule.Entry(entryIndex);\n\n    int index = entryIndex;\n\n    while (index > 0)\n    {\n        const ScheduleEntry &previous =\n            schedule.Entry(index - 1);\n\n        if (previous.Year != target.Year ||\n            previous.Month != target.Month ||\n            previous.Day != target.Day)\n        {\n            break;\n        }\n\n        index--;\n    }\n\n    return index;\n}\n\nint FindDateEnd(\n    int entryIndex)\n{\n    if (entryIndex < 0 ||\n        entryIndex >= schedule.Count())\n    {\n        return -1;\n    }\n\n    const ScheduleEntry &target =\n        schedule.Entry(entryIndex);\n\n    int index = entryIndex;\n\n    while (index + 1 < schedule.Count())\n    {\n        const ScheduleEntry &next =\n            schedule.Entry(index + 1);\n\n        if (next.Year != target.Year ||\n            next.Month != target.Month ||\n            next.Day != target.Day)\n        {\n            break;\n        }\n\n        index++;\n    }\n\n    return index;\n}\n\nint FindPageStartForEntry(\n    int entryIndex)\n{\n    int dateStart =\n        FindDateStart(\n            entryIndex);\n\n    if (dateStart < 0)\n    {\n        return -1;\n    }\n\n    int offset =\n        entryIndex -\n        dateStart;\n\n    return\n        dateStart +\n        (offset /\n         ScheduleLayout::EntriesPerPage) *\n        ScheduleLayout::EntriesPerPage;\n}\n\nbool HasNextSchedulePage()\n{\n    if (schedulePageStart < 0 ||\n        schedulePageStart >= schedule.Count())\n    {\n        return false;\n    }\n\n    int dateEnd =\n        FindDateEnd(\n            schedulePageStart);\n\n    int nextWithinDate =\n        schedulePageStart +\n        ScheduleLayout::EntriesPerPage;\n\n    if (nextWithinDate <= dateEnd)\n    {\n        return true;\n    }\n\n    return\n        dateEnd + 1 <\n        schedule.Count();\n}\n\nbool HasPreviousSchedulePage()\n{\n    return\n        schedulePageStart > 0 &&\n        schedule.Count() > 0;\n}\n'
text = text[:start] + new_schedule_code + text[end:]

marker = '    return\n        point.Y >= top &&\n        point.Y < bottom;\n}\n'
replacement = '    return\n        point.Y >= top &&\n        point.Y < bottom;\n}\n\n\nbool IsTouchRegion(\n    const TouchPoint &point,\n    int left,\n    int right,\n    int top,\n    int bottom)\n{\n    return\n        point.X >= left &&\n        point.X < right &&\n        point.Y >= top &&\n        point.Y < bottom;\n}\n'
